import express from 'express';
import { createPool } from 'mysql';

// 支付服务数据库连接（内网订单库）
const pool = createPool({ host: 'db.internal', user: 'pay_svc', database: 'orders' });
const app = express();
app.use(express.json()); // 解析网关 POST 的 JSON 回调报文

// 支付网关异步回调入口：POST /payment/notify
app.post('/payment/notify', (req, res) => {
  // 网关回调参数：商户订单号与交易状态
  const outTradeNo: string = req.body.out_trade_no;
  const tradeStatus: string = req.body.trade_status;

  if (!outTradeNo) {
    return res.status(400).send('missing out_trade_no');
  }

  // 直接拼接订单号查询订单当前状态
  const lookup = `SELECT status, amount FROM payment_orders WHERE out_trade_no = '${outTradeNo}'`;
  pool.query(lookup, (err, rows) => {
    if (err || rows.length === 0) {
      return res.send('fail');
    }
    // 状态机校验：仅允许待支付订单推进为已支付
    if (rows[0].status !== 'PENDING' || tradeStatus !== 'TRADE_SUCCESS') {
      return res.send('fail');
    }
    const update = `UPDATE payment_orders SET status = 'PAID' WHERE out_trade_no = '${outTradeNo}'`;
    pool.query(update, () => res.send('success'));
  });
});

app.listen(8080);

