import fs from 'fs';
import path from 'path';

// 订单处理后台任务：从队列拉取订单导出作业，将对账单写入归档目录
const ARCHIVE_ROOT = '/var/data/order_archive';

interface OrderJob {
  orderId: string;
  archiveSubdir: string; // 客户在导出设置中自定义的归档子目录名
  amountCents: number;
}

// 入口：消息队列消费者回调，raw 为外部提交的作业报文
export function onOrderJobMessage(raw: string): string {
  const job: OrderJob = JSON.parse(raw);
  const summary = `order=${job.orderId} amount=${job.amountCents}\n`;
  // 直接使用客户可控的子目录名拼接归档路径，未做越界校验
  const targetDir = path.join(ARCHIVE_ROOT, job.archiveSubdir);
  fs.mkdirSync(targetDir, { recursive: true });
  const targetFile = path.join(targetDir, `${job.orderId}.txt`);
  fs.writeFileSync(targetFile, summary, 'utf8');
  return targetFile;
}

import express from 'express';
import fs from 'fs';

const app = express();
app.use(express.json());

// 简易过滤：仅移除 <script> 标签字面量，未处理事件属性等注入向量
function stripScript(s: string): string {
  return s.replace(/<script>/gi, '');
}

// 报表导出服务：根据查询参数生成 HTML 报表并返回
app.get('/export/report', (req, res) => {
  // 入口：报表标题由用户通过 URL 查询参数直接传入
  const title = stripScript(req.query.title as string);
  // 备用入口：过滤条件同样来自查询参数，未经过任何处理
  const filter = (req.query.filter as string) || 'all';

  // 模拟从数据库读取统计数据
  const stats = { total: 1024, failed: 3 };

  // 用户输入未经 HTML 实体转义直接拼入模板
  const html = `<html><body>
    <h1>报表：${title}</h1>
    <p>过滤条件：${filter}</p>
    <p>总计：${stats.total}，失败：${stats.failed}</p>
  </body></html>`;

  // 将含用户输入的 HTML 持久化为导出文件
  const outPath = `/tmp/exports/report-${Date.now()}.html`;
  fs.writeFileSync(outPath, html);
  // 以 text/html 回显给浏览器
  res.type('text/html').send(html);
});

