using System;
using System.Net.Http;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;

namespace AuditApi.Controllers
{
    // 审计日志查询：代理转发前端指定的日志聚合节点查询
    [ApiController]
    [Route("api/audit")]
    public class AuditLogController : ControllerBase
    {
        private static readonly HttpClient _client = new HttpClient();

        [HttpGet("query")]
        public async Task<IActionResult> QueryAuditLog()
        {
            // 入口：直接读取查询串参数，未做来源校验
            string logNode = Request.Query["logNode"].ToString();
            string range = Request.Query["range"].ToString();

            // 拼接目标 URL：logNode 占据主机位，完全由客户端控制
            string targetUrl = logNode + "/audit/logs?range=" + Uri.EscapeDataString(range);

            // sink：向该地址发起服务端 HTTP 请求
            HttpResponseMessage resp = await _client.GetAsync(targetUrl);
            string body = await resp.Content.ReadAsStringAsync();

            // 原样回显响应，构成可读取内网内容的回显型 SSRF
            return Content(body, "application/json");
        }
    }
}

import java.io.File
import java.nio.file.Files
import java.nio.file.Paths
import io.ktor.server.application.*
import io.ktor.server.response.*
import io.ktor.server.routing.*

// 静态资源根目录(图片/文档等公共文件)
val WEB_ROOT = File("/var/www/static")

fun Route.staticResourceApi() {
    // 入口1: GET /static?file=logo.png 图片预览
    get("/static") {
        val name = call.request.queryParameters["file"] ?: return@get
        val target = File(WEB_ROOT, name)              // 直接拼接, 未做路径规范化
        if (target.exists() && target.isFile) {
            call.response.headers.append("Content-Type", "application/octet-stream")
            call.respondBytes(target.readBytes())      // sink1: 文件内容直接回显
        }
    }
    // 入口2: GET /download?path=docs/a.pdf 文档下载
    get("/download") {
        val rel = call.request.queryParameters["path"] ?: return@get
        val p = Paths.get(WEB_ROOT.absolutePath, rel)  // NIO 通道同样未校验
        if (Files.isRegularFile(p)) {
            call.respondBytes(Files.readAllBytes(p))   // sink2: 任意文件读取
        }
    }
}

import java.io.ByteArrayInputStream
import javax.xml.parsers.DocumentBuilderFactory
import org.w3c.dom.Document

// 图片处理流水线：解析上传图片内嵌的 XMP 元数据并写入搜索索引
class ImageXmpPipeline {

    // 入口：上传回调，imageBytes 为用户可控的原始图片字节
    fun onImageUploaded(imageBytes: ByteArray) {
        val xmp = extractXmpPacket(imageBytes) ?: return
        val doc = parseXmp(xmp)
        val title = doc.getElementsByTagName("dc:title").item(0)?.textContent
        saveToIndex(title ?: "")
    }

    // XMP 以明文 XML 内嵌于图片 APP1 段，直接按字节定位切片
    private fun extractXmpPacket(imageBytes: ByteArray): ByteArray? {
        val text = String(imageBytes, Charsets.ISO_8859_1)
        val start = text.indexOf("<x:xmpmeta")
        if (start < 0) return null
        val end = text.indexOf("</x:xmpmeta>")
        if (end < 0) return null
        return imageBytes.copyOfRange(start, end + 12)
    }

    // 解析 XMP：使用默认配置的 DocumentBuilderFactory，未禁用 DTD 与外部实体
    private fun parseXmp(xmp: ByteArray): Document {
        val factory = DocumentBuilderFactory.newInstance()
        val builder = factory.newDocumentBuilder()
        return builder.parse(ByteArrayInputStream(xmp))
    }

    private fun saveToIndex(title: String) {
        // 写入搜索索引（略）
    }
}

import * as fs from 'fs';
import * as path from 'path';

// 订单归档根目录：服务端常量，不受任何外部输入影响
const ARCHIVE_ROOT = '/var/data/order-archive';

// 白名单允许集：后台任务仅支持导出以下三种订单报表
enum ReportKind {
  Daily = 'daily',
  Monthly = 'monthly',
  Refund = 'refund',
}

// 枚举到固定相对路径的硬编码映射，路径内容与用户输入无关
const REPORT_FILES: Record<ReportKind, string> = {
  [ReportKind.Daily]: 'reports/daily-summary.csv',
  [ReportKind.Monthly]: 'reports/monthly-summary.csv',
  [ReportKind.Refund]: 'reports/refund-list.csv',
};

// 订单处理后台任务：队列消费者按报表类型读取归档文件
export function runOrderExportJob(rawKind: string): string {
  // 防御点：精确白名单校验，rawKind 必须逐字命中枚举成员
  if (!Object.values(ReportKind).includes(rawKind)) {
    throw new Error('unsupported report kind');
  }
  const kind = rawKind as ReportKind;
  // 数据流改道：最终路径来自映射常量，rawKind 仅作查找键
  const target = path.join(ARCHIVE_ROOT, REPORT_FILES[kind]);
  return fs.readFileSync(target, 'utf8');
}

import { Pool } from 'pg';

// 专用只读连接池：连接串指向数据库角色 payment_callback_ro，
// 该角色仅被授予视图 v_payment_status 的 SELECT，无任何基表或写权限；
// 第 8 行再以会话参数 default_transaction_read_only=on 由服务端强制只读。
const roPool = new Pool({
  connectionString: process.env.PAYMENT_CALLBACK_RO_DSN,
  options: '-c default_transaction_read_only=on',
  max: 5,
});

export async function handlePaymentCallback(body: { orderId?: string; status?: string }) {
  const orderId = String(body.orderId ?? '');
  const status = String(body.status ?? '');
  if (orderId.length === 0 || orderId.length > 64) {
    return { ok: false, reason: 'bad orderId' };
  }
  // 表面危险：外部输入 orderId 被字符串拼接进 SQL（CWE-89 触感）
  const sql = "SELECT state, amount FROM v_payment_status WHERE order_id = '" + orderId + "'";
  const client = await roPool.connect();
  try {
    const res = await client.query(sql);
    if (res.rowCount === 0) {
      return { ok: false, reason: 'order not found' };
    }
    // status 不进入任何 SQL，仅作为返回字段；写库由独立服务以参数化语句完成
    return { ok: true, state: res.rows[0].state, nextStatus: status };
  } finally {
    client.release();
  }
}

import { promises as fsp } from 'fs';
import * as path from 'path';

// 订单处理后台任务：按调度器下发的报表类型读取预生成的订单汇总归档
enum OrderReportKind {
  DailySummary = 'daily-summary',
  WeeklySettlement = 'weekly-settlement',
  MonthlyInvoice = 'monthly-invoice',
}

const REPORT_FILES: Record<OrderReportKind, string> = {
  [OrderReportKind.DailySummary]: 'reports/daily-summary.csv',
  [OrderReportKind.WeeklySettlement]: 'reports/weekly-settlement.csv',
  [OrderReportKind.MonthlyInvoice]: 'reports/monthly-invoice.csv',
};

const REPORT_ROOT = '/var/lib/order-worker/reports';

function isOrderReportKind(value: string): value is OrderReportKind {
  return (Object.values(OrderReportKind) as string[]).includes(value);
}

export async function collectOrderReport(rawKind: string): Promise<string> {
  if (!isOrderReportKind(rawKind)) {
    throw new Error(`拒绝未知报表类型: ${rawKind}`);
  }
  const fixedRelPath = REPORT_FILES[rawKind];
  const absolutePath = path.join(REPORT_ROOT, fixedRelPath);
  const content = await fsp.readFile(absolutePath, 'utf8');
  console.info(`订单后台任务读取报表: kind=${rawKind}`);
  return content.slice(0, 200);
}

// feed-import-adapter.ts —— 数据导入适配器：拉取租户配置的订阅源并统计记录数
import { SecureFetch } from '@platform/net-guard';

export interface ImportJob {
  tenantId: string;
  feedUrl: string; // 导入向导中由用户填写的订阅地址，属不可信输入
}

// 平台统一出网客户端：ssrfGuard 默认开启，此处显式保持 true。
// 防护在连接层生效：先解析 DNS，再对解析出的每个 IP 做范围校验，
// 命中环回/私网/链路本地/云元数据地址即拒绝建连；重定向每一跳均复检。
// 本服务未设置 NET_GUARD_DISABLE=1，也未传入 allowPrivateNetwork: true。
const client = new SecureFetch({
  ssrfGuard: true,
  maxRedirects: 3,
  timeoutMs: 5000,
});

function parseFeed(body: string): number {
  const data = JSON.parse(body) as { records?: unknown[] };
  return Array.isArray(data.records) ? data.records.length : 0;
}

export async function runImport(job: ImportJob): Promise<number> {
  const target = new URL(job.feedUrl);
  if (target.protocol !== 'http:' && target.protocol !== 'https:') {
    throw new Error('仅支持 http/https 订阅地址');
  }
  // 表面危险点：不可信 URL 直接进入出网请求，呈 CWE-918 形态
  const resp = await client.get(target, { headers: { accept: 'application/json' } });
  const body = await resp.text();
  const records = parseFeed(body);
  return records.length;
}

// 会话管理组件：解析并校验客户端提交的会话有效期（TTL）
// 表面风险：RE_SESSION_TTL 含嵌套量词，属 CWE-1333 典型 ReDoS 模式

const RE_SESSION_TTL: RegExp = /^(\d+)+[smhd]?$/;
const MAX_TTL_SECONDS = 604800; // 7 天上限

interface SessionTtl {
  seconds: number;
  token: string;
}

export function parseSessionTtl(rawTtl: string): SessionTtl | null {
  // 强类型转换：原始串先经 parseInt 变为 number，病态构造的超长回溯串
  // 在此被压缩为安全整数或被整体拒绝，无法以原样抵达正则
  const seconds = Number.parseInt(rawTtl, 10);
  if (!Number.isSafeInteger(seconds) || seconds <= 0 || seconds > MAX_TTL_SECONDS) {
    return null;
  }
  // 正则的真正输入是规范数字串，与攻击者原始串完全无关
  const token = seconds.toString(10);
  if (!RE_SESSION_TTL.test(token)) {
    return null;
  }
  return { seconds, token };
}

export function extendSession(sessionId: string, rawTtl: string): string {
  const meta = parseSessionTtl(rawTtl);
  if (meta === null) {
    return `session ${sessionId} ttl rejected`;
  }
  // 审计返回串只包含转换后的数值与规范 token，原始串不再进入任何通道
  return `session ${sessionId} extended by ${meta.seconds}s token=${meta.token}`;
}
